import * as React from "react";
import { cx } from "./cx";

export interface EmptyProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "title"> {
  title?: React.ReactNode;
  action?: React.ReactNode;
}

/** A vacant cell. Title, one sentence, optional action. */
export function Empty({ title, action, className, children, ...props }: EmptyProps) {
  return (
    <div className={cx("rs-empty", className)} {...props}>
      {title != null && <p className="rs-empty-title">{title}</p>}
      {children != null && <p className="rs-empty-body">{children}</p>}
      {action != null && <div className="rs-empty-action">{action}</div>}
    </div>
  );
}

/** Join class names, dropping falsy parts. */
export function cx(...parts: Array<string | false | null | undefined>): string {
  return parts.filter(Boolean).join(" ");
}

/* ── Empty: a quiet vacant cell, not an illustration ── */
.rs-empty{display:flex;flex-direction:column;justify-content:center;gap:8px;min-height:204px;padding:20px;border:1px solid var(--divider);border-radius:0}
.rs-empty-title{margin:0;font-size:15px;font-weight:600;letter-spacing:-.01em;color:var(--text)}
.rs-empty-body{margin:0;font-size:13.5px;line-height:1.55;letter-spacing:-.01em;color:var(--text-secondary)}
.rs-empty-action{margin-top:8px;width:fit-content}
